import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, m] = lines[0].split(" ").map(Number);

// dist[i * n + j] = i から j への最短距離（0 始まり）
const dist = new Float64Array(n * n).fill(Infinity);
for (let i = 0; i < n; i++) dist[i * n + i] = 0;
for (let k = 1; k <= m; k++) {
  const [u, v, w] = lines[k].split(" ").map(Number);
  const idx = (u - 1) * n + (v - 1);
  dist[idx] = Math.min(dist[idx], w);
}

// ワーシャル–フロイド法: 経由してよい頂点を 1 つずつ増やす
for (let k = 0; k < n; k++) {
  for (let i = 0; i < n; i++) {
    const ik = dist[i * n + k];
    if (ik === Infinity) continue;
    for (let j = 0; j < n; j++) {
      const via = ik + dist[k * n + j];
      if (via < dist[i * n + j]) dist[i * n + j] = via;
    }
  }
}

const q = Number(lines[m + 1]);
const out: number[] = [];
for (let i = 0; i < q; i++) {
  const [s, t] = lines[m + 2 + i].split(" ").map(Number);
  const d = dist[(s - 1) * n + (t - 1)];
  out.push(d === Infinity ? -1 : d);
}
console.log(out.join("\n"));
